SELECT id, tenant_id, role_code, role_name, role_desc, is_system, role_type, sort_order, create_by, update_by, create_time, update_time FROM role WHERE (tenant_id = #{tenantId} OR (tenant_id = 1 AND is_system = 1 AND role_code != 'SUPER_ADMIN'
AND role_type IN #{t}
)) AND is_deleted = 0
AND role_name LIKE CONCAT('%', #{roleName}, '%')
AND role_code LIKE CONCAT('%', #{roleCode}, '%')
ORDER BY id ASC

